#include <vector>
#include <cstddef>
#include <omp.h>

double productWithInverses(std::vector<double> const& x) {
    const std::size_t n = x.size();
    if (n == 0) return 1.0;

    int max_threads = 1;
    #pragma omp parallel
    {
        #pragma omp single
        max_threads = omp_get_num_threads();
    }

    std::vector<double> partial(max_threads, 1.0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        double local_prod = 1.0;

        #pragma omp for schedule(static)
        for (std::size_t i = 0; i < n; ++i) {
            local_prod *= ((i & 1u) == 0u) ? x[i] : (1.0 / x[i]);
        }

        partial[tid] = local_prod;  // unique index per thread, no race
    }

    double product = 1.0;
    for (double v : partial) {
        product *= v;
    }

    return product;
}
